package br.com.aconchego.rpd;
import android.test.InstrumentationTestCase;
import android.content.*;
import android.webkit.WebView;
import android.view.*;
import android.graphics.Bitmap;
import org.json.*;
import java.io.*;
import java.util.concurrent.*;

public class JournalTest extends InstrumentationTestCase {
 private JSONObject record(String id)throws Exception{JSONObject r=new JSONObject();r.put("id",id).put("title","Encontro de teste").put("date","2026-10-18T09:30").put("status","open").put("updatedAt",1).put("before",55).put("after",JSONObject.NULL);for(String k:new String[]{"situation","body","emotion","thought","consequence","evidenceFor","evidenceAgainst","alternatives","friend","response","next","notes"})r.put(k,"");return r.put("situation","Uma conversa no trabalho").put("emotion","Ansiedade").put("response","Posso fazer uma pausa e conversar com calma.");}
 public void testAtomicMigrationDraftsAndBackup()throws Exception{
  File dir=new File(getInstrumentation().getTargetContext().getCacheDir(),"test-"+System.nanoTime());assertTrue(dir.mkdir());JSONObject old=record("11111111-1111-4111-8111-111111111111");try(FileOutputStream out=new FileOutputStream(new File(dir,"records.json"))){out.write(new JSONArray().put(old).toString().getBytes("UTF-8"));}
  JournalStore s=new JournalStore(dir);assertEquals(1,s.state().getJSONArray("records").length());JSONObject edited=new JSONObject(old.toString()).put("thought","Rascunho que deve sobreviver ao fechamento.");s.draft(new JSONObject().put("record",edited).put("step",2).put("quick",false).put("savedAt",2));s=new JournalStore(dir);assertEquals("Rascunho que deve sobreviver ao fechamento.",s.state().getJSONArray("drafts").getJSONObject(0).getJSONObject("record").getString("thought"));assertEquals("",s.state().getJSONArray("records").getJSONObject(0).getString("thought"));
  assertTrue(s.favorite(old.getString("id"),true).getBoolean("favorite"));assertTrue(s.state().getJSONArray("drafts").getJSONObject(0).getJSONObject("record").getBoolean("favorite"));s.prefs(new JSONObject().put("theme","dark").put("fontSize","large").put("motion",false));
  JSONObject backup=s.backup();File dest=new File(dir,"restored");assertTrue(dest.mkdir());JournalStore restored=new JournalStore(dest);assertEquals(1,restored.restore(backup,true).getInt("added"));assertEquals("dark",restored.state().getJSONObject("prefs").getString("theme"));assertTrue(restored.state().getJSONArray("records").getJSONObject(0).getBoolean("favorite"));assertEquals(1,restored.restore(backup,true).getInt("kept"));assertEquals(1,restored.state().getJSONArray("drafts").length());
  JSONObject changed=new JSONObject(old.toString()).put("title","Versão atual");restored.save(changed);restored.restore(backup,false);assertEquals("Versão atual",restored.state().getJSONArray("records").getJSONObject(0).getString("title"));String before=restored.state().toString();JSONObject bad=new JSONObject(backup.toString());bad.getJSONArray("records").getJSONObject(0).put("id","invalido");try{restored.restore(bad,true);fail("Backup inválido aceito");}catch(IOException expected){}assertEquals(before,restored.state().toString());s.save(edited);assertEquals(0,s.state().getJSONArray("drafts").length());assertEquals(1,new JournalStore(dir).state().getJSONArray("records").length());
 }
 private MainActivity activity;private WebView web;
 private WebView findWeb(View view){if(view instanceof WebView)return (WebView)view;if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int i=0;i<group.getChildCount();i++){WebView found=findWeb(group.getChildAt(i));if(found!=null)return found;}}return null;}
 private String js(String code)throws Exception{CountDownLatch latch=new CountDownLatch(1);String[] result={null};getInstrumentation().runOnMainSync(()->web.evaluateJavascript(code,value->{result[0]=value;latch.countDown();}));assertTrue("JavaScript timeout",latch.await(10,TimeUnit.SECONDS));return result[0];}
 private void until(String expr)throws Exception{for(int i=0;i<50;i++){if("true".equals(js(expr)))return;Thread.sleep(200);}fail("Condição não atingida: "+expr+"\n"+js("document.body.innerText"));}
 private void click(String text)throws Exception{js("Array.from(document.querySelectorAll('button')).find(b=>b.textContent.trim()==="+JSONObject.quote(text)+")?.click()");}
 private void screenshot(String name)throws Exception{Thread.sleep(400);getInstrumentation().waitForIdleSync();Bitmap image=getInstrumentation().getUiAutomation().takeScreenshot();try(FileOutputStream out=new FileOutputStream(new File(getInstrumentation().getTargetContext().getFilesDir(),name+".png"))){image.compress(Bitmap.CompressFormat.PNG,100,out);}image.recycle();String pkg=getInstrumentation().getTargetContext().getPackageName();try(android.os.ParcelFileDescriptor fd=getInstrumentation().getUiAutomation().executeShellCommand("run-as "+pkg+" cat files/"+name+".png > /data/local/tmp/"+name+".png");InputStream in=new android.os.ParcelFileDescriptor.AutoCloseInputStream(fd)){byte[] buffer=new byte[1024];while(in.read(buffer)!=-1){}}}
 public void testWebViewQuickDraftPreferencesPdfAndLockGate()throws Exception{
  Intent intent=new Intent(getInstrumentation().getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);activity=(MainActivity)getInstrumentation().startActivitySync(intent);getInstrumentation().runOnMainSync(()->web=findWeb(activity.findViewById(android.R.id.content)));until("document.body.innerText.includes('Registro rápido')");until("document.fonts.check('16px AconchegoBook')");screenshot("home-v2");
  awaitFont();click("Registro rápido");until("document.body.innerText.includes('Só o essencial')");js("(()=>{const e=document.querySelector('textarea');Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype,'value').set.call(e,'Uma conversa de teste, com calma.');e.dispatchEvent(new Event('input',{bubbles:true}));})()");until("JSON.parse(AconchegoNative.getState()).drafts.some(d=>d.record.situation==='Uma conversa de teste, com calma.')");click("Ajustes");until("document.querySelector('select[aria-label=\"Aparência\"]')!==null");js("(()=>{const e=document.querySelector('select[aria-label=\"Aparência\"]');e.value='dark';e.dispatchEvent(new Event('change',{bubbles:true}));})()");until("document.documentElement.dataset.theme==='dark'");js("(()=>{const e=document.querySelector('select[aria-label=\"Tamanho da letra\"]');e.value='larger';e.dispatchEvent(new Event('change',{bubbles:true}));})()");until("getComputedStyle(document.documentElement).getPropertyValue('--scale').trim()==='1.3'");screenshot("settings-dark-v2");click("Meu espaço");until("document.body.innerText.includes('Continuar de onde parei')");
  JSONObject r=record("22222222-2222-4222-8222-222222222222");js("AconchegoNative.save("+JSONObject.quote(r.toString())+")");js("AconchegoNative.setFavorite('22222222-2222-4222-8222-222222222222',true);window.dispatchEvent(new Event('aconchego-ready'))");click("Favoritos");until("document.body.innerText.includes('Posso fazer uma pausa')");screenshot("favorites-v2");
  js("window.pdfTest='loading';Promise.all(['/vendor/pdf-lib.min.js','/pdf-export.js'].map(src=>new Promise((ok,no)=>{const s=document.createElement('script');s.src=src;s.onload=ok;s.onerror=no;document.head.appendChild(s);}))).then(()=>AconchegoPDF.generate([],{title:'Resumo revisado',period:'18/10/2026 a 24/10/2026',body:'Texto de teste com acentuação e reflexão.'})).then(bytes=>{window.pdfTest=String.fromCharCode(...bytes.slice(0,5));}).catch(e=>window.pdfTest=String(e));");until("window.pdfTest==='%PDF-'");
  java.lang.reflect.Field access=MainActivity.class.getDeclaredField("unlocked");access.setAccessible(true);access.setBoolean(activity,false);assertTrue(new JSONObject(activity.new Bridge().list()).has("error"));assertTrue(new JSONObject(activity.new Bridge().save(r.toString())).has("error"));assertTrue(new JSONObject(activity.new Bridge().exportBackup()).has("error"));access.setBoolean(activity,true);
  getInstrumentation().runOnMainSync(()->activity.finish());
 }
 private void awaitFont()throws Exception{until("document.fonts.status==='loaded'");}
}
